create table dict_funkcja_szczegolowa
(
    kod                         varchar(8)           not null
        constraint dict_funkcja_szczegolowa_pk
            primary key,
    funkcja_szczegolowa_budynku varchar(49),
    czy_ogrzewany               boolean default true not null
);

comment on table dict_funkcja_szczegolowa is 'Tabela z kodami KŚT';

